  // 碰撞解算：给定位置与半径，迭代推出所有重叠盒
  collide(px, pz, radius) {
    let x = px, z = pz;
    for (let i = 0; i < 3; i++) {   // 多次迭代提高稳定性
      for (const b of this.boxes) {
        const push = b.resolveCircle(x, z, radius);
        if (push) { x += push.x; z += push.z; }
      }
    }
    // 外围边界裁剪
    x = Math.max(this.bounds.minX + radius, Math.min(this.bounds.maxX - radius, x));
    z = Math.max(this.bounds.minZ + radius, Math.min(this.bounds.maxZ - radius, z));
    return { x, z };
  }

  // 射线 vs 全部 AABB，返回最近相交点距离（保留旧接口，供敌人视线检测等使用）
  raycast(origin, direction, maxDist) {
    return this.raycastDetailed(origin, direction, maxDist).t;
  }

  // 高精度：返回 { t, normal }——最近命中距离 + 命中面世界法线（弹孔精确贴墙）
  raycastDetailed(origin, direction, maxDist) {
    let best = { t: maxDist, normal: null };
    for (const b of this.boxes) {
      const r = rayAABBDetailed(origin, direction, b);
      if (r !== null && r.t < best.t) best = r;
    }
    return best;
  }
}

